ox":[19,1,12,22,4,16]},{"name":"Formal dining room","box":[31,1,12,34,4,16]},{"name":"Kitchen and great room","box":[19,1,18,34,4,24]},{"name":"Family room","box":[36,1,13,41,4,23]},{"name":"Bay nook","box":[39,1,9,41,4,11]},{"name":"Mudroom and laundry","box":[2,1,19,16,4,23]},{"name":"Garage","box":[2,1,8,16,4,17]},{"name":"Gallery landing","box":[24,6,17,29,8,24]},{"name":"West passage","box":[19,6,18,22,8,19]},{"name":"East passage","box":[31,6,18,34,8,19]},{"name":"Bedroom 2","box":[19,6,12,22,8,16]},{"name":"Bedroom 3","box":[31,6,12,34,8,16]},{"name":"Bedroom 4","box":[19,6,21,22,8,24]},{"name":"Primary bedroom","box":[36,6,13,41,8,19]},{"name":"Primary sitting nook","box":[39,6,9,41,8,11]},{"name":"Primary bath","box":[36,6,21,41,8,23]},{"name":"Walk-in closet","box":[31,6,21,34,8,24]},{"name":"Bonus room","box":[2,6,8,16,8,23]}]}#!/bin/sh
# Makes build.nbt from scratch: build.mjs to a temp file, then the roof preset check once the shell exists, then mv.
set -eu
cd "$(dirname "$0")"
MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs
tmp=build.tmp.nbt
trap 'rm -f "$tmp"' EXIT

node build.mjs "$tmp"

# The roofs are built in node by roofSpec (parts/roofs.mjs), so this preset step is a dry-run report only (it writes
# nothing); running it for real would put a second roof over the first.
if grep -q '^// STUB' parts/main-shell.mjs; then
  echo "roof step skipped: the shell is still a stub"
else
  node "$MCD" roof "$tmp" --preset cottage --style hip --material dark-slate --dry-run
fi

mv "$tmp" build.nbt
echo "wrote build.nbt"
